'use client';

import React, { useEffect, useRef, useState } from 'react';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { getSupabaseClient } from '../lib/supabase';

type Tab = 'share' | 'view';
type Role = 'host' | 'viewer';

type SignalMessage =
  | { type: 'join-request'; from: string }
  | { type: 'offer'; from: string; sdp: RTCSessionDescriptionInit }
  | { type: 'answer'; from: string; sdp: RTCSessionDescriptionInit }
  | { type: 'ice-candidate'; from: string; candidate: RTCIceCandidateInit };

type PresenceState = Record<string, Array<Record<string, unknown>>>;

const ICE_SERVERS: RTCIceServer[] = [
  { urls: 'stun:stun.l.google.com:19302' },
];

function makeRoomId() {
  return `room-${crypto.randomUUID().slice(0, 8)}`;
}

function makeClientId() {
  return crypto.randomUUID();
}

function buildInviteUrl(roomId: string) {
  const inviteUrl = new URL(window.location.origin + window.location.pathname);
  inviteUrl.searchParams.set('room', roomId);
  return inviteUrl.toString();
}

function ScreenShare() {
  const [tab, setTab] = useState<Tab>('share');
  const [roomId, setRoomId] = useState('');
  const [shareLink, setShareLink] = useState('');
  const [isSharing, setIsSharing] = useState(false);
  const [isViewing, setIsViewing] = useState(false);
  const [viewerConnected, setViewerConnected] = useState(false);
  const [copyStatus, setCopyStatus] = useState('');
  const [shareError, setShareError] = useState('');
  const [viewError, setViewError] = useState('');
  const [supabaseError, setSupabaseError] = useState('');
  const [joinRoomId, setJoinRoomId] = useState('');

  const localVideoRef = useRef<HTMLVideoElement | null>(null);
  const remoteVideoViewRef = useRef<HTMLVideoElement | null>(null);

  const localStreamRef = useRef<MediaStream | null>(null);
  const channelRef = useRef<RealtimeChannel | null>(null);
  const pcRef = useRef<RTCPeerConnection | null>(null);
  const pendingCandidatesRef = useRef<RTCIceCandidateInit[]>([]);
  const clientIdRef = useRef<string>(makeClientId());
  const roleRef = useRef<Role | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const room = params.get('room');
    if (room) {
      setJoinRoomId(room);
      setTab('view');
    }
  }, []);

  useEffect(() => {
    return () => {
      mountedRef.current = false;
      void teardownSession();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function updateConnectionStatus() {
    const state = pcRef.current?.iceConnectionState ?? 'new';
    if (roleRef.current === 'host') {
      setViewerConnected(state === 'connected' || state === 'completed');
    }
    if (roleRef.current === 'viewer') {
      setIsViewing(state === 'connected' || state === 'completed' || isViewing);
    }
  }

  function getViewerCount(channel: RealtimeChannel) {
    const presence = channel.presenceState() as PresenceState;
    return Object.values(presence)
      .flat()
      .filter((entry) => entry.role === 'viewer').length;
  }

  function refreshPresenceStatus(channel: RealtimeChannel) {
    if (roleRef.current === 'host') {
      setViewerConnected(getViewerCount(channel) > 0);
    }
  }

  async function sendSignal(
    channel: RealtimeChannel,
    event: SignalMessage['type'],
    payload: Record<string, unknown>
  ) {
    await channel.send({
      type: 'broadcast',
      event,
      payload,
    });
  }

  async function flushPendingCandidates(pc: RTCPeerConnection) {
    const pending = pendingCandidatesRef.current.splice(0);
    for (const candidate of pending) {
      await pc.addIceCandidate(new RTCIceCandidate(candidate));
    }
  }

  function setupPeerConnection(role: Role) {
    const pc = new RTCPeerConnection({ iceServers: ICE_SERVERS });
    roleRef.current = role;
    pcRef.current = pc;

    pc.onicecandidate = (event) => {
      const channel = channelRef.current;
      if (!channel || !event.candidate) return;
      void sendSignal(channel, 'ice-candidate', {
        from: clientIdRef.current,
        candidate: event.candidate.toJSON(),
      });
    };

    pc.oniceconnectionstatechange = () => {
      updateConnectionStatus();
      const state = pc.iceConnectionState;
      if (state === 'failed' || state === 'disconnected' || state === 'closed') {
        if (role === 'host') {
          setViewerConnected(false);
          if (pcRef.current) {
            try {
              pcRef.current.close();
            } catch {}
            pcRef.current = null;
          }
        } else {
          setIsViewing(false);
        }
      }
    };

    if (role === 'viewer') {
      const remoteStream = new MediaStream();
      pc.ontrack = (event) => {
        event.streams[0]?.getTracks().forEach((track) => remoteStream.addTrack(track));
        if (remoteVideoViewRef.current) {
          remoteVideoViewRef.current.srcObject = remoteStream;
        }
      };
    }

    return pc;
  }

  async function initiateHostOffer() {
    const localStream = localStreamRef.current;
    const channel = channelRef.current;
    if (!localStream || !channel || pcRef.current || roleRef.current !== 'host') return;

    const pc = setupPeerConnection('host');
    localStream.getTracks().forEach((track) => pc.addTrack(track, localStream));

    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    await sendSignal(channel, 'offer', {
      from: clientIdRef.current,
      sdp: pc.localDescription ?? offer,
    });
  }

  async function handleOffer(sdp: RTCSessionDescriptionInit) {
    if (roleRef.current !== 'viewer') return;

    const channel = channelRef.current;
    if (!channel) return;

    const pc = pcRef.current ?? setupPeerConnection('viewer');
    await pc.setRemoteDescription(new RTCSessionDescription(sdp));
    await flushPendingCandidates(pc);

    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);
    await sendSignal(channel, 'answer', {
      from: clientIdRef.current,
      sdp: pc.localDescription ?? answer,
    });
  }

  async function handleAnswer(sdp: RTCSessionDescriptionInit) {
    const pc = pcRef.current;
    if (!pc || roleRef.current !== 'host') return;
    await pc.setRemoteDescription(new RTCSessionDescription(sdp));
    await flushPendingCandidates(pc);
    setViewerConnected(true);
  }

  async function handleCandidate(candidate: RTCIceCandidateInit) {
    const pc = pcRef.current;
    if (!pc) {
      pendingCandidatesRef.current.push(candidate);
      return;
    }

    if (!pc.remoteDescription) {
      pendingCandidatesRef.current.push(candidate);
      return;
    }

    await pc.addIceCandidate(new RTCIceCandidate(candidate));
  }

  async function openRoomChannel(room: string, role: Role) {
    const supabase = getSupabaseClient();
    const channel = supabase.channel(room, {
      config: {
        broadcast: { self: false },
        presence: { key: clientIdRef.current },
      },
    });
    channelRef.current = channel;

    channel.on('broadcast', { event: 'join-request' }, ({ payload }) => {
      const data = payload as { from?: string };
      if (role === 'host' && data.from && data.from !== clientIdRef.current) {
        void initiateHostOffer();
      }
    });

    channel.on('broadcast', { event: 'offer' }, ({ payload }) => {
      const data = payload as { from?: string; sdp?: RTCSessionDescriptionInit };
      if (role === 'viewer' && data.sdp) {
        void handleOffer(data.sdp);
      }
    });

    channel.on('broadcast', { event: 'answer' }, ({ payload }) => {
      const data = payload as { from?: string; sdp?: RTCSessionDescriptionInit };
      if (role === 'host' && data.sdp) {
        void handleAnswer(data.sdp);
      }
    });

    channel.on('broadcast', { event: 'ice-candidate' }, ({ payload }) => {
      const data = payload as { from?: string; candidate?: RTCIceCandidateInit };
      if (data.candidate) {
        void handleCandidate(data.candidate);
      }
    });

    channel.on('presence', { event: 'sync' }, () => {
      refreshPresenceStatus(channel);
      if (role === 'host' && localStreamRef.current && !pcRef.current && getViewerCount(channel) > 0) {
        void initiateHostOffer();
      }
    });

    channel.on('presence', { event: 'join' }, () => {
      refreshPresenceStatus(channel);
      if (role === 'host' && localStreamRef.current && !pcRef.current && getViewerCount(channel) > 0) {
        void initiateHostOffer();
      }
    });

    channel.on('presence', { event: 'leave' }, () => {
      refreshPresenceStatus(channel);
      if (role === 'host' && getViewerCount(channel) === 0) {
        setViewerConnected(false);
        if (pcRef.current) {
          try {
            pcRef.current.close();
          } catch {}
          pcRef.current = null;
        }
      }
      if (role === 'viewer' && getViewerCount(channel) === 0) {
        setIsViewing(false);
      }
    });

    channel.subscribe(async (status) => {
      if (!mountedRef.current) return;

      if (status === 'SUBSCRIBED') {
        await channel.track({
          clientId: clientIdRef.current,
          role,
          joinedAt: new Date().toISOString(),
        });

        if (role === 'viewer') {
          await sendSignal(channel, 'join-request', { from: clientIdRef.current });
        }
      }

      if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
        const message = role === 'host' ? 'Failed to open room channel' : 'Failed to join room channel';
        if (role === 'host') {
          setShareError(message);
          setIsSharing(false);
        } else {
          setViewError(message);
          setIsViewing(false);
        }
      }
    });
    return channel;
  }

  async function teardownSession() {
    const channel = channelRef.current;
    channelRef.current = null;

    const pc = pcRef.current;
    pcRef.current = null;
    pendingCandidatesRef.current = [];

    if (pc) {
      try {
        pc.close();
      } catch {}
    }

    if (channel) {
      try {
        await getSupabaseClient().removeChannel(channel);
      } catch {}
    }

    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach((track) => track.stop());
      localStreamRef.current = null;
    }

    if (localVideoRef.current) {
      localVideoRef.current.srcObject = null;
    }

    if (remoteVideoViewRef.current) {
      remoteVideoViewRef.current.srcObject = null;
    }
  }

  function createMeetingLink() {
    setShareError('');
    setCopyStatus('');
    const nextRoomId = makeRoomId();
    const nextShareLink = buildInviteUrl(nextRoomId);
    setRoomId(nextRoomId);
    setShareLink(nextShareLink);
    window.history.replaceState(null, '', nextShareLink);
  }

  async function startSharing() {
    setShareError('');
    setCopyStatus('');
    setViewerConnected(false);
    setSupabaseError('');

    try {
      getSupabaseClient();
    } catch (err) {
      setShareError(err instanceof Error ? err.message : 'Supabase is not configured');
      return;
    }

    const nextRoomId = roomId || makeRoomId();
    const nextShareLink = buildInviteUrl(nextRoomId);
    setRoomId(nextRoomId);
    setShareLink(nextShareLink);
    window.history.replaceState(null, '', nextShareLink);

    try {
      await teardownSession();
      const stream = await navigator.mediaDevices.getDisplayMedia({
        video: true,
        audio: true,
      });

      localStreamRef.current = stream;
      if (localVideoRef.current) {
        localVideoRef.current.srcObject = stream;
      }

      stream.getVideoTracks().forEach((track) => {
        track.addEventListener('ended', () => {
          void stopSharing();
        });
      });
      roleRef.current = 'host';
      await openRoomChannel(nextRoomId, 'host');
      setIsSharing(true);
    } catch (err) {
      setShareError(err instanceof Error ? err.message : 'Failed to start screen sharing');
    }
  }

  async function stopSharing() {
    await teardownSession();
    roleRef.current = null;
    setIsSharing(false);
    setViewerConnected(false);
  }

  async function copyShareLink() {
    if (!shareLink) return;
    try {
      await navigator.clipboard.writeText(shareLink);
      setCopyStatus('Copied!');
      setTimeout(() => setCopyStatus(''), 1500);
    } catch {
      setCopyStatus('Copy failed');
      setTimeout(() => setCopyStatus(''), 1500);
    }
  }

  async function joinRoom() {
    setViewError('');
    setSupabaseError('');

    const targetRoom = joinRoomId.trim();
    if (!targetRoom) {
      setViewError('Enter a room ID');
      return;
    }

    try {
      getSupabaseClient();
    } catch (err) {
      setViewError(err instanceof Error ? err.message : 'Supabase is not configured');
      return;
    }

    await teardownSession();
    roleRef.current = 'viewer';
    setIsViewing(true);

    try {
      await openRoomChannel(targetRoom, 'viewer');
    } catch (err) {
      setViewError(err instanceof Error ? err.message : 'Failed to join room');
    }
  }

  async function leaveRoom() {
    await teardownSession();
    roleRef.current = null;
    setIsViewing(false);
  }

  function goFullscreen() {
    const el = remoteVideoViewRef.current;
    if (!el) return;
    if (el.requestFullscreen) {
      el.requestFullscreen().catch(() => {});
    }
  }

  return (
    <div
      style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: 920,
        margin: '0 auto',
        padding: 24,
      }}
    >
      <h1 style={{ marginBottom: 8 }}>ShareScreen</h1>
      <p style={{ marginBottom: 20, color: '#6b7280' }}>
        Supabase Realtime signaling with direct WebRTC screen sharing.
      </p>

      {(shareError || viewError || supabaseError) && (
        <p style={{ color: 'crimson', marginBottom: 16 }}>
          {shareError || viewError || supabaseError}
        </p>
      )}

      <div
        style={{
          display: 'flex',
          gap: 8,
          margin: '16px 0',
          borderBottom: '1px solid #ddd',
        }}
      >
        <button
          onClick={() => setTab('share')}
          style={{
            padding: '8px 16px',
            border: 'none',
            background: 'transparent',
            borderBottom: tab === 'share' ? '2px solid #2563eb' : '2px solid transparent',
            fontWeight: tab === 'share' ? 600 : 400,
            cursor: 'pointer',
          }}
        >
          Share Screen
        </button>
        <button
          onClick={() => setTab('view')}
          style={{
            padding: '8px 16px',
            border: 'none',
            background: 'transparent',
            borderBottom: tab === 'view' ? '2px solid #2563eb' : '2px solid transparent',
            fontWeight: tab === 'view' ? 600 : 400,
            cursor: 'pointer',
          }}
        >
          View Screen
        </button>
      </div>

      {tab === 'share' && (
        <section>
          <div
            style={{
              display: 'flex',
              gap: 8,
              alignItems: 'center',
              marginBottom: 12,
              flexWrap: 'wrap',
            }}
          >
            {!isSharing && (
              <button
                onClick={createMeetingLink}
                style={{
                  padding: '8px 14px',
                  background: '#111827',
                  color: 'white',
                  border: 'none',
                  borderRadius: 6,
                  cursor: 'pointer',
                }}
              >
                Create Meeting Link
              </button>
            )}

            {!isSharing ? (
              <button
                onClick={startSharing}
                style={{
                  padding: '8px 14px',
                  background: '#2563eb',
                  color: 'white',
                  border: 'none',
                  borderRadius: 6,
                  cursor: 'pointer',
                }}
              >
                {roomId ? 'Start Sharing' : 'Create and Start'}
              </button>
            ) : (
              <button
                onClick={stopSharing}
                style={{
                  padding: '8px 14px',
                  background: '#dc2626',
                  color: 'white',
                  border: 'none',
                  borderRadius: 6,
                  cursor: 'pointer',
                }}
              >
                Stop Sharing
              </button>
            )}
          </div>

          {shareLink && (
            <div
              style={{
                display: 'flex',
                gap: 8,
                alignItems: 'center',
                marginBottom: 12,
                flexWrap: 'wrap',
              }}
            >
              <span>Invite link:</span>
              <code
                style={{
                  background: '#f3f4f6',
                  padding: '4px 8px',
                  borderRadius: 4,
                  maxWidth: '100%',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                }}
              >
                {shareLink}
              </code>
              <button
                onClick={copyShareLink}
                style={{
                  padding: '6px 10px',
                  border: '1px solid #ccc',
                  borderRadius: 6,
                  background: 'white',
                  cursor: 'pointer',
                }}
              >
                Copy Link
              </button>
              {copyStatus && <span style={{ color: '#16a34a' }}>{copyStatus}</span>}
              <span
                style={{
                  marginLeft: 'auto',
                  fontSize: 14,
                  color: viewerConnected ? '#16a34a' : '#6b7280',
                }}
              >
                {viewerConnected ? '● Viewer connected' : '○ Waiting for viewer…'}
              </span>
            </div>
          )}

          <div
            style={{
              display: 'grid',
              gridTemplateColumns: '1fr',
              gap: 12,
            }}
          >
            <div>
              <p style={{ margin: '8px 0', fontSize: 14, color: '#6b7280' }}>
                Your screen preview
              </p>
              <video
                ref={localVideoRef}
                autoPlay
                playsInline
                muted
                style={{
                  width: '100%',
                  background: '#000',
                  borderRadius: 6,
                  aspectRatio: '16 / 9',
                }}
              />
            </div>
          </div>
        </section>
      )}

      {tab === 'view' && (
        <section>
          <div
            style={{
              display: 'flex',
              gap: 8,
              alignItems: 'center',
              marginBottom: 12,
              flexWrap: 'wrap',
            }}
          >
            <input
              type="text"
              placeholder="Enter room ID"
              value={joinRoomId}
              onChange={(e) => setJoinRoomId(e.target.value)}
              disabled={isViewing}
              style={{
                padding: '8px 10px',
                border: '1px solid #ccc',
                borderRadius: 6,
                minWidth: 240,
              }}
            />

            {!isViewing ? (
              <button
                onClick={joinRoom}
                style={{
                  padding: '8px 14px',
                  background: '#2563eb',
                  color: 'white',
                  border: 'none',
                  borderRadius: 6,
                  cursor: 'pointer',
                }}
              >
                Join
              </button>
            ) : (
              <button
                onClick={leaveRoom}
                style={{
                  padding: '8px 14px',
                  background: '#dc2626',
                  color: 'white',
                  border: 'none',
                  borderRadius: 6,
                  cursor: 'pointer',
                }}
              >
                Leave
              </button>
            )}

            <button
              onClick={goFullscreen}
              disabled={!isViewing}
              style={{
                padding: '8px 14px',
                border: '1px solid #ccc',
                borderRadius: 6,
                background: 'white',
                cursor: 'pointer',
              }}
            >
              Fullscreen
            </button>
          </div>

          <video
            ref={remoteVideoViewRef}
            autoPlay
            playsInline
            controls
            style={{
              width: '100%',
              background: '#000',
              borderRadius: 6,
              aspectRatio: '16 / 9',
            }}
          />
        </section>
      )}
    </div>
  );
}

export default ScreenShare;
